def run(ctx):
    """把命令的 stdout/stderr 一起回给模型——报错也是信息。"""
    out = str(ctx.text or '')
    ctx.state.setdefault('history', []).append(out[:2000])
    tail = out[-4000:] if len(out) > 4000 else out
    return {'data': f'【执行输出】\n{tail}'}
